import java.io.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    static long[][] multiply(long[][] a, long[][] b) {
        long[][] c = new long[26][26];
        for (int i = 0; i < 26; i++)
            for (int k = 0; k < 26; k++) {
                if (a[i][k] == 0) continue;
                for (int j = 0; j < 26; j++) c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % MOD;
            }
        return c;
    }

    public static void main(String[] args) throws IOException {
        InputStream in = System.in;
        byte[] buf = new byte[1 << 16];
        long[] counts = new long[26];
        StringBuilder rest = new StringBuilder();
        boolean firstLine = true;
        for (int len; (len = in.read(buf)) > 0;) {
            for (int i = 0; i < len; i++) {
                int ch = buf[i];
                if (firstLine) {
                    if (ch == '\n') firstLine = false;
                    else if (ch >= 'a' && ch <= 'z') counts[ch - 'a']++;
                } else if (ch >= '0' && ch <= '9') rest.append((char) ch);
                else if (rest.length() > 0) { firstLine = false; break; }
            }
        }
        long t = rest.length() == 0 ? 0 : Long.parseLong(rest.toString());
        // Column j of base is what one copy of letter j becomes after one round.
        long[][] base = new long[26][26], result = new long[26][26];
        for (int i = 0; i < 26; i++) result[i][i] = 1;
        for (int i = 0; i < 25; i++) base[i + 1][i] = 1;
        base[0][25] = 1;
        base[1][25] = 1;
        while (t > 0) {
            if ((t & 1) == 1) result = multiply(result, base);
            base = multiply(base, base);
            t >>= 1;
        }
        long answer = 0;
        for (int i = 0; i < 26; i++)
            for (int j = 0; j < 26; j++) answer = (answer + result[i][j] * (counts[j] % MOD)) % MOD;
        System.out.println(answer);
    }
}

package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"
)

const MOD = 1000000007

type matrix [26][26]int64

func multiply(a, b *matrix) *matrix {
	c := new(matrix)
	for i := 0; i < 26; i++ {
		for k := 0; k < 26; k++ {
			if a[i][k] == 0 {
				continue
			}
			for j := 0; j < 26; j++ {
				c[i][j] = (c[i][j] + a[i][k]*b[k][j]) % MOD
			}
		}
	}
	return c
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	line, rest := data, []byte{}
	if i := bytes.IndexByte(data, '\n'); i >= 0 {
		line, rest = data[:i], data[i+1:]
	}
	var counts [26]int64
	for _, ch := range line {
		if ch >= 'a' && ch <= 'z' {
			counts[ch-'a']++
		}
	}
	fields := bytes.Fields(rest)
	var t uint64
	if len(fields) > 0 {
		t, _ = strconv.ParseUint(string(fields[0]), 10, 64)
	}
	// Column j of base is what one copy of letter j becomes after one round.
	base, result := new(matrix), new(matrix)
	for i := 0; i < 26; i++ {
		result[i][i] = 1
	}
	for i := 0; i < 25; i++ {
		base[i+1][i] = 1
	}
	base[0][25], base[1][25] = 1, 1
	for ; t > 0; t >>= 1 {
		if t&1 == 1 {
			result = multiply(result, base)
		}
		base = multiply(base, base)
	}
	var answer int64
	for i := 0; i < 26; i++ {
		for j := 0; j < 26; j++ {
			answer = (answer + result[i][j]*(counts[j]%MOD)) % MOD
		}
	}
	fmt.Println(answer)
}
